function setupTimer(){$("#timerStart").onclick=()=>state.focus?.running?pauseTimer():startTimer();$("#timerReset").onclick=resetTimer;$$("[data-min]").forEach(b=>b.onclick=()=>{if(state.focus?.running||state.focus?.paused){toast("Reset the current timer before changing duration.");return}chosenMinutes=Number(b.dataset.min);$$("[data-min]").forEach(x=>x.classList.toggle("selected",x===b));timerDisplay()});$("#setCustom").onclick=()=>{const n=Math.max(1,Math.min(180,Number($("#customMinutes").value)||25));if(state.focus){toast("Reset the current timer first.");return}chosenMinutes=n;$$("[data-min]").forEach(x=>x.classList.remove("selected"));timerDisplay()};$("#startNow").onclick=()=>{go("focus");startTimer()}}
function setupCanvas(){const c=$("#drawingCanvas"),ctx=c.getContext("2d");ctx.lineCap="round";ctx.lineJoin="round";let drawing=false,last=null,erase=false;function pos(e){const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}}c.addEventListener("pointerdown",e=>{drawing=true;last=pos(e);c.setPointerCapture(e.pointerId)});c.addEventListener("pointermove",e=>{if(!drawing)return;const p=pos(e);ctx.strokeStyle=erase?"#ffffff":$("#penColor").value;ctx.lineWidth=Number($("#penSize").value)*(c.width/c.clientWidth);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p});["pointerup","pointercancel"].forEach(ev=>c.addEventListener(ev,()=>drawing=false));$("#eraser").onclick=()=>{erase=!erase;$("#eraser").textContent=erase?"Eraser on":"Eraser"};$("#clearCanvas").onclick=()=>{if(confirm("Clear this diagram?"))ctx.clearRect(0,0,c.width,c.height)};$("#saveDiagram").onclick=()=>{const a=document.createElement("a");a.download="studyhub-diagram-"+today()+".png";a.href=c.toDataURL("image/png");a.click();toast("Diagram PNG downloaded.")}}
function beginSimulator(){if(!state.questions.length){toast("Add questions in Practice Arena first.");return}const count=Math.max(1,Math.min(state.questions.length,Number($("#simCount").value)||10));simState={items:[...state.questions].sort(()=>Math.random()-.5).slice(0,count),answers:{},endAt:Date.now()+Math.max(5,Number($("#simDuration").value)||30)*60000,index:0};renderSim();clearInterval(simTick);simTick=setInterval(()=>{if(!simState)return;const left=Math.max(0,Math.ceil((simState.endAt-Date.now())/1000));$("#simClock").textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,"0")}`;if(left<=0)submitSim()},500)}
function renderSim(){const q=simState.items[simState.index];$("#simArea").classList.remove("hidden");$("#simArea").innerHTML=`<div class="section-head"><h3>Question ${simState.index+1}/${simState.items.length}</h3><span class="pill" id="simClock"></span></div><h3>${esc(q.text)}</h3>${q.options.map((o,i)=>`<label class="option"><input type="radio" name="simAnswer" value="${i}" ${simState.answers[q.id]===i?"checked":""}> ${"ABCD"[i]}. ${esc(o)}</label>`).join("")}<div class="row-actions"><button class="btn secondary" id="simPrev" ${simState.index===0?"disabled":""}>Previous</button><button class="btn secondary" id="simNext">${simState.index===simState.items.length-1?"Review":"Next"}</button><button class="btn" id="simSubmit">Submit paper</button></div>`;$$('input[name="simAnswer"]').forEach(x=>x.onchange=()=>simState.answers[q.id]=Number(x.value));$("#simPrev").onclick=()=>{simState.index--;renderSim()};$("#simNext").onclick=()=>{simState.index=(simState.index+1)%simState.items.length;renderSim()};$("#simSubmit").onclick=submitSim;const left=Math.max(0,Math.ceil((simState.endAt-Date.now())/1000));$("#simClock").textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,"0")}`}
function submitSim(){if(!simState)return;clearInterval(simTick);let score=0;simState.items.forEach(q=>{if(simState.answers[q.id]===q.correct)score++});const total=simState.items.length;state.quizHistory.push({id:uid(),date:new Date().toISOString(),score,total,mode:"Timed exam simulation"});state.xp+=score*4;simState=null;save();$("#simArea").innerHTML=`<div class="empty"><h2>Simulation submitted</h2><div class="timer">${score}/${total}</div><p>${Math.round(score/total*100)}% accuracy. Review the topics you found difficult.</p><button class="btn" data-page="practice">Open practice arena</button></div>`;bindNav();renderQuizHistory();renderDashboard()}
function setupAI(){$("#coachRun").onclick=()=>{const weak=state.chapters.filter(c=>!c.done).slice(0,3),due=dueCards().length,open=state.tasks.filter(t=>!t.done&&t.date<=today()).length;$("#coachResult").innerHTML=`<div class="notice"><b>Your next steps</b><ul>${weak.length?weak.map(c=>`<li>Continue ${esc(c.subject)}: ${esc(c.title)}</li>`).join(""):"<li>Add exact chapter titles to your subject checklist.</li>"}<li>${due?`Review ${due} flashcards due today.`:"Create 2–3 flashcards from today's lesson."}</li><li>${open?`You have ${open} unfinished or due mission(s). Choose one manageable task.`:"Plan one focused session for your next subject."}</li></ul><small>This is a rule-based helper using local data, not generative AI.</small></div>`};$("#generatePrompts").onclick=()=>{const s=$("#genSubject").value,t=$("#genTopic").value.trim()||"your chosen topic";$("#generatedPrompts").innerHTML=`<div class="panel"><ol><li>Explain the key idea in ${esc(t)} in your own words.</li><li>List five important terms from ${esc(t)} and define them.</li><li>Create three short-answer questions about ${esc(t)}.</li><li>What is one common misconception in ${esc(t)}?</li><li>Teach ${esc(t)} to a younger student in five simple steps.</li></ol><button class="tiny primary" id="copyPrompts">Copy prompts</button></div>`;$("#copyPrompts").onclick=()=>navigator.clipboard?.writeText(`Subject: ${s}\\nTopic: ${t}\\n1. Explain the key idea in your own words.\\n2. List five important terms and define them.\\n3. Create three short-answer questions.\\n4. Identify a common misconception.\\n5. Teach it in five simple steps.`).then(()=>toast("Prompts copied")).catch(()=>toast("Copy not available in this browser"))}}
function setupBackup(){$("#exportBackup").onclick=()=>{const blob=new Blob([JSON.stringify({app:"StudyHub",exportedAt:new Date().toISOString(),data:state},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="StudyHub-backup-"+today()+".json";a.click();URL.revokeObjectURL(a.href);toast("Backup downloaded.")};$("#importBackup").onclick=()=>{const f=$("#importFile").files[0];if(!f){toast("Choose a JSON backup file first.");return}const r=new FileReader();r.onload=()=>{try{const parsed=JSON.parse(r.result);const d=parsed.data||parsed;if(!d||!Array.isArray(d.tasks)||!Array.isArray(d.notes)||!d.programme)throw Error("Invalid backup");if(!confirm("This replaces current StudyHub data. Continue?"))return;state={...defaults(),...d};save();renderAll();toast("Backup restored.")}catch(e){toast("This file is not a valid StudyHub backup.")}};r.readAsText(f)}}
