function cloudStatus(message,badge){const el=$('#cloudSyncStatus'),b=$('#cloudSyncBadge'),a=$('#authStatus');if(el)el.textContent=message;if(a)a.textContent=message;if(b&&badge)b.textContent=badge;const connected=!!cloudUser;['#cloudSyncNow','#cloudSignOut'].forEach(id=>{const x=$(id);if(x)x.disabled=!connected});const email=$('#accountEmail'),desc=$('#accountDescription');if(email)email.textContent=connected?cloudUser.email:'Guest mode · This device';if(desc)desc.textContent=connected?'Your private StudyHub data is connected to cloud sync.':'Sign in to synchronise your learning data across devices.';const pageEmail=$('#accountPageEmail'),pageTitle=$('#accountPageTitle');if(pageEmail)pageEmail.textContent=connected?cloudUser.email:'Guest mode · This device';if(pageTitle)pageTitle.textContent=connected?'Your account is connected':'Your StudyHub account';['#openAuthPage','#accountPageSignIn'].forEach(id=>{const btn=$(id);if(btn)btn.classList.toggle('hidden',connected)})}
