async function pushCloudState(showMessage=true){if(!cloudClient||!cloudUser||cloudBusy)return;const revisionAtStart=cloudRevision;cloudBusy=true;cloudStatus("Syncing your latest changes…","Syncing");try{const stamp=new Date().toISOString();const {error}=await cloudClient.from("studyhub_user_data").upsert({user_id:cloudUser.id,data:state,updated_at:stamp},{onConflict:"user_id"});if(error)throw error;cloudLastUpdated=stamp;if(cloudRevision===revisionAtStart)cloudLocalDirty=false;cloudStatus("Synced just now · "+cloudUser.email,"Synced");if(showMessage)toast("StudyHub synced across your devices.")}catch(e){console.error("StudyHub cloud sync:",e);cloudStatus("Sync failed: "+(e.message||"check your Supabase table, policies and connection")+". Your local copy is safe; retrying shortly.","Sync error");if(cloudUser&&cloudLocalDirty)setTimeout(()=>pushCloudState(false),5000)}finally{cloudBusy=false;if(cloudRevision!==revisionAtStart&&cloudUser)setTimeout(()=>pushCloudState(false),600)}}
async function pullCloudState(){if(!cloudClient||!cloudUser)return;cloudStatus("Checking your cloud backup…","Loading");try{const {data,error}=await cloudClient.from("studyhub_user_data").select("data,updated_at").eq("user_id",cloudUser.id).maybeSingle();if(error)throw error;if(data?.data){cloudLastUpdated=data.updated_at;const hasLocal=state.tasks.length||state.notes.length||state.chapters.length||state.cards.length||state.sessions.length||state.exams.length||state.questions.length;if(hasLocal){const useCloud=confirm("A StudyHub cloud backup already exists (last updated "+new Date(data.updated_at).toLocaleString()+"). OK = download cloud data and replace this device's StudyHub records. Cancel = keep this device's data and upload it to the cloud instead.");if(useCloud){cloudHydrating=true;state={...defaults(),...data.data};await persistLocalOnly();renderAll();cloudHydrating=false;cloudLocalDirty=false;cloudStatus("Cloud data loaded on this device.","Synced");toast("Cloud StudyHub data restored.")}else{await pushCloudState(true)}}else{cloudHydrating=true;state={...defaults(),...data.data};await persistLocalOnly();renderAll();cloudHydrating=false;cloudLocalDirty=false;cloudStatus("Cloud data loaded on this device.","Synced")}}else{await pushCloudState(false);cloudStatus("Account connected. Your local StudyHub data is now backed up.","Synced")}}catch(e){cloudHydrating=false;console.error("StudyHub cloud restore:",e);cloudStatus("Could not load cloud data: "+(e.message||"check database setup"),"Sync error")}}
